ctx.shadowColor='#58f0e1';ctx.shadowBlur=18;ctx.fillStyle='#58f0e1';roundRect(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.shadowBlur=0;ctx.fillStyle='#d7fffa';roundRect(paddle.x+14,paddle.y+3,paddle.w-28,3,2);
ctx.shadowColor='#fff';ctx.shadowBlur=22;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.35);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;if(ball.stuck){ctx.fillStyle='#b5bfdf';ctx.font='12px system-ui';ctx.fillText('Pulsa Espacio o haz clic para lanzar',W/2,H-12)}}
function pointer(e){const r=canvas.getBoundingClientRect();mouseX=(e.clientX-r.left)*W/r.width}
canvas.addEventListener('pointermove',pointer);canvas.addEventListener('pointerdown',e=>{pointer(e);if("'!running||paused){start();return}if(ball.stuck)ball.stuck=false});window.addEventListener('"'keydown',e=>{if(['ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '){if("'!running||paused){start()}else pause()}if(e.key==='"'r'||e.key==='R'){ended=true;running=false;score=0;lives=3;level=1;makeBricks();resetBall();updateUI();show('¿Listo para jugar?','Rompe todos los ladrillos y supera los 2 niveles. ¡Que no se te escape la bola"'!'"','Empezar partida')}});window.addEventListener('keyup',e=>keys[e.key]=false);startBtn.addEventListener('click',start);makeBricks();resetBall();updateUI();draw();
})();
</script>
