function draw(){ctx.clearRect(0,0,W,H);const g=ctx.createRadialGradient(W/2,H*.45,0,W/2,H*.45,H*.72);g.addColorStop(0,'"'#151a36');g.addColorStop(1,'#090c1b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#ffffff09';ctx.lineWidth=1;for(let x=30;x<W;x+=45){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=25;y<H;y+=45){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.fillStyle='#a9b3db66';ctx.font='700 11px system-ui';ctx.textAlign='center';ctx.fillText('NIVEL '+level,W/2,30);
for(const b of bricks){ctx.shadowColor=b.color;ctx.shadowBlur=12;ctx.fillStyle=b.color;roundRect(b.x,b.y,b.w,b.h,6);ctx.shadowBlur=0;ctx.fillStyle='#ffffff2b';roundRect(b.x+3,b.y+3,b.w-6,4,2);if(b.hp>1){ctx.fillStyle='#35172b';ctx.font='bold 11px system-ui';ctx.fillText('◆',b.x+b.w/2,b.y+16)}}
ctx.shadowColor='#58f0e1';ctx.shadowBlur=18;ctx.fillStyle='#58f0e1';roundRect(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.shadowBlur=0;ctx.fillStyle='#d7fffa';roundRect(paddle.x+14,paddle.y+3,paddle.w-28,3,2);
ctx.shadowColor='#fff';ctx.shadowBlur=22;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.35);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;if(ball.stuck){ctx.fillStyle='#b5bfdf';ctx.font='12px system-ui';ctx.fillText('Pulsa Espacio o haz clic para lanzar',W/2,H-12)}}
function pointer(e){const r=canvas.getBoundingClientRect();mouseX=(e.clientX-r.left)*W/r.width}
